input.command:
mkdir -p ~/development/.tmp/stallion-cf && cat > ~/development/.tmp/stallion-cf/store.mjs <<'EOF'
import { readFileSync, mkdirSync, writeFileSync, chmodSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { homedir } from "node:os";
import { join } from "node:path";

const value = readFileSync(join(homedir(), "development/dotfiles/cloudflare_token.txt"), "utf8").trim();
if (!value || /\s/.test(value)) {
  console.log("bad format");
  process.exit(1);
}
console.log("ok");

const gh = spawnSync("gh", ["secret", "set", "CLOUDFLARE_API_TOKEN", "--repo", "mvhenten/stallion"], {
  input: value,
  stdio: ["pipe", "inherit", "inherit"],
});
if (gh.status !== 0) {
  console.log(`gh secret set failed: ${gh.status}`);
  process.exit(1);
}

const dir = join(homedir(), ".config/stallion");
mkdirSync(dir, { recursive: true, mode: 0o700 });
chmodSync(dir, 0o700);
const file = join(dir, "cf-env");
writeFileSync(file, `CLOUDFLARE_API_TOKEN=${value}\nCLOUDFLARE_ACCOUNT_ID=f496802dcadb597e5939f6449c759a43\n`, { mode: 0o600 });
chmodSync(file, 0o600);
console.log("env written");
EOF
node ~/development/.tmp/stallion-cf/store.mjs; cd ~/development/dotfiles && git check-ignore -v cloudflare_token.txt; git ls-files --error-unmatch cloudflare_token.txt 2>&1 | head -1

